p='/app/output/runs/tilted_far_pre/meta.json';m=json.load(open(p));c=m['cameras']['wrist_left'];K=np.array(c['intrinsic_cv']);E=np.array(c['extrinsic_cv']);R=E[:3,:3];t=E[:3,3];C=-R.T@t
print('C',C,'K',K,'E',E)
for uv in [(415,245),(405,265),(390,260),(424,240),(245,130)]:
 d=R.T@np.linalg.inv(K)@np.array([uv[0],uv[1],1.]);
 for z in [.78,.82,.86]:
  xyz=C+(z-C[2])/d[2]*d
  print(uv,z,np.round(xyz,3))
