from pathlib import Path
p=Path('/app/output/runs')
items=[]
for d in p.iterdir():
 if d.is_dir():
  m=d/'meta.json'
  if m.exists():
   try:
    x=json.loads(m.read_text()); items.append((m.stat().st_mtime,d.name,x))
   except: pass
for _,n,x in sorted(items)[-12:]:
 print(n, x.get('done'), x.get('reason'), x.get('control_steps_chunk'), x.get('plan'), x.get('clipped'))
print('newest dirs')
for d in sorted(p.iterdir(),key=lambda d:d.stat().st_mtime)[-10:]: print(d.name, d.stat().st_mtime)
